/**
 * Learner disclosure permissions for exact values. These only control what authorized recruiters
 * receive; proofs and policy outcomes are generated by the backend regardless of these settings.
 */
import { useEffect, useState } from "react";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import {
  getDisclosurePreferencesApi,
  updateDisclosurePreferencesApi,
  type DisclosurePreferences,
} from "@/services/api/wallet.api";

type Key = "shareExactAssessmentMarks" | "shareExactGithubCommitCount";

const SETTINGS: Array<{ key: Key; id: string; label: string; off: string; on: string }> = [
  {
    key: "shareExactAssessmentMarks",
    id: "share-exact-marks",
    label: "Share exact assessment marks",
    off: "Recruiters see only whether you met the 60% policy.",
    on: "Authorized recruiters with your share link also see your exact marks.",
  },
  {
    key: "shareExactGithubCommitCount",
    id: "share-exact-commits",
    label: "Share exact GitHub commit count",
    off: "Recruiters see only whether a repository met the 70-commit policy.",
    on: "Authorized recruiters with your share link also see exact commit counts.",
  },
];

export function WalletPrivacySettingsCard() {
  const [prefs, setPrefs] = useState<DisclosurePreferences | null>(null);
  const [saving, setSaving] = useState<Key | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    getDisclosurePreferencesApi()
      .then(setPrefs)
      .catch(() => setPrefs({ shareExactAssessmentMarks: false, shareExactGithubCommitCount: false, updatedAt: null }));
  }, []);

  const toggle = async (key: Key, value: boolean) => {
    setSaving(key);
    setError(null);
    try {
      setPrefs(await updateDisclosurePreferencesApi({ [key]: value }));
    } catch (err) {
      setError(err instanceof Error ? err.message : "Could not save this setting.");
    } finally {
      setSaving(null);
    }
  };

  return (
    <div className="learner-stat-card space-y-3 p-4">
      <div>
        <p className="text-sm font-semibold text-[#023E8A]">Privacy settings</p>
        <p className="mt-1 text-xs text-[#64748b]">
          SIJIL verifies your evidence automatically. These settings only decide whether recruiters see exact values.
        </p>
      </div>
      {SETTINGS.map((setting) => {
        const checked = prefs?.[setting.key] === true;
        return (
          <div key={setting.key} className="flex items-start justify-between gap-3 rounded-lg border p-3">
            <div>
              <Label htmlFor={setting.id} className="text-sm text-[#023E8A]">{setting.label}</Label>
              <p className="text-xs text-[#64748b]">{checked ? setting.on : setting.off}</p>
            </div>
            <Switch
              id={setting.id}
              checked={checked}
              disabled={!prefs || saving !== null}
              onCheckedChange={(value) => void toggle(setting.key, value)}
            />
          </div>
        );
      })}
      {error ? <p className="text-xs text-red-700">{error}</p> : null}
    </div>
  );
}
